cases.setup_script:
H=/opt/bashos-parity/harness/helpers/transfer-rollback-evidence-r3.py
/usr/bin/python3 "$H" prepare || { echo 'CONTROL-FAILED signed input'; exit 98; }
/usr/bin/cp "$H" "$HOME/rollback-backend" && /usr/bin/chmod 700 "$HOME/rollback-backend" && /usr/bin/cmp -s "$H" "$HOME/rollback-backend" || { echo 'CONTROL-FAILED backend copy'; exit 98; }
if [[ -x /bash-os/bl-pkg.sh ]]; then printf '%s\n' 'image backend takes precedence; pinned mock not used' > "$HOME/backend-selection.txt"; echo 'CONTROL-FAILED image backend precedence'; exit 98; fi
printf '%s\n' 'image backend not executable; BASHPKG_BLPKG_PATH selects pinned mock' > "$HOME/backend-selection.txt"
/usr/bin/python3 "$H" control || { echo 'CONTROL-FAILED backend transaction'; exit 98; }
/usr/bin/python3 "$H" snapshot root before || exit 98
"$HOME/rollback-backend" seed root > "$HOME/seed.out" 2> "$HOME/seed.err" || { echo 'CONTROL-FAILED seed'; exit 98; }
txn=$(<"$HOME/rollback-txn-root")
/usr/bin/python3 "$H" snapshot root installed || exit 98
